<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { Head, Link } from '@inertiajs/vue3';
import axios from 'axios';
import Button from 'primevue/button';
import ConfirmDialog from 'primevue/confirmdialog';
import Select from 'primevue/select';
import Toast from 'primevue/toast';
import { useConfirm } from 'primevue/useconfirm';
import { useToast } from 'primevue/usetoast';
import { useI18n } from 'vue-i18n';
import InventoryNav from '../../../Components/Common/InventoryNav.vue';

interface Unit { id:number;name:string;symbol:string;factor:string }
interface Stock { location_id:number;quantity:string }
interface Product { id:number;sku:string;name:string;category_id:number;category_name:string;base_unit_symbol:string;average_cost:string;stock_quantity:string;stocks:Stock[];units:Unit[] }
interface Location { id:number;name:string;warehouse_id:number;warehouse_code:string;warehouse_name:string;warehouse_address:string|null }
interface Responsible { id:number;name:string;code:string }
const props=defineProps<{mode:'exit'|'transfer';products:Product[];locations:Location[];responsibles:Responsible[];today:string}>();
const toast=useToast();const confirm=useConfirm();const {t}=useI18n();const saving=ref(false);const resultId=ref<number|null>(null);const errors=ref<Record<string,string[]>>({});const pending=ref<Record<string,unknown>|null>(null);const categoryId=ref<number|''>('');
const storageKey=computed(()=>`vidrieria.inventory.pending-${props.mode}`);
const form=reactive({product_id:'' as number|'',location_id:'' as number|'',unit_id:'' as number|'',source_location_id:'' as number|'',destination_location_id:'' as number|'',responsible_name:'',reason:'sale',document_date:props.today,reference:'',notes:'',quantity:''});
const availableProducts=computed(()=>props.products.filter(item=>Number(item.stock_quantity)>0&&(categoryId.value===''||item.category_id===categoryId.value)).map(item=>({...item,label:`${item.sku} — ${item.name} · ${item.stock_quantity} ${item.base_unit_symbol}`})));
const categories=computed(()=>Array.from(new Map(props.products.map(item=>[item.category_id,item.category_name])),([id,name])=>({id,name})).sort((a,b)=>a.name.localeCompare(b.name,'es')));
const product=computed(()=>props.products.find(item=>item.id===form.product_id));
const positiveLocationIds=computed(()=>new Set((product.value?.stocks??[]).filter(item=>Number(item.quantity)>0).map(item=>item.location_id)));
const sourceLocations=computed(()=>props.locations.filter(item=>positiveLocationIds.value.has(item.id)));
const destinationLocations=computed(()=>props.locations.filter(item=>item.id!==form.source_location_id));
const title=computed(()=>t(props.mode==='exit'?'inventory.operations.exitTitle':'inventory.operations.transferTitle'));
const selectedUnit=computed(()=>product.value?.units.find(unit=>unit.id===form.unit_id));
const productLabel=computed(()=>product.value?`${product.value.sku} — ${product.value.name}`:'');

onMounted(()=>{const saved=sessionStorage.getItem(storageKey.value);if(saved){try{pending.value=JSON.parse(saved) as Record<string,unknown>;toast.add({severity:'warn',summary:t('inventory.operations.pendingTitle'),detail:t('inventory.operations.pendingDetail'),life:7000})}catch{sessionStorage.removeItem(storageKey.value)}}});
watch(()=>form.product_id,()=>{form.unit_id=product.value?.units[0]?.id??'';form.location_id='';form.source_location_id='';form.destination_location_id=''});
watch(categoryId,()=>{if(product.value&&categoryId.value!==''&&product.value.category_id!==categoryId.value)form.product_id=''});
watch(()=>form.source_location_id,()=>{if(form.destination_location_id===form.source_location_id)form.destination_location_id=''});

function payload():Record<string,unknown>{const common={operation_key:crypto.randomUUID(),product_id:Number(form.product_id),document_date:form.document_date,reference:form.reference.trim()||null,notes:form.notes.trim()||null,quantity:form.quantity.trim()};return props.mode==='exit'?{...common,location_id:Number(form.location_id),unit_id:Number(form.unit_id),reason:form.reason}:{...common,source_location_id:Number(form.source_location_id),destination_location_id:Number(form.destination_location_id),responsible_name:form.responsible_name.trim()}}
function submit():void{if(saving.value||resultId.value!==null)return;if(pending.value!==null){void save();return}confirm.require({header:t(props.mode==='exit'?'inventory.operations.confirmExit':'inventory.operations.confirmTransfer'),message:props.mode==='exit'?t('inventory.operations.exitQuestion',{quantity:form.quantity||'0',unit:selectedUnit.value?.symbol??'',product:product.value?.name??t('common.product').toLowerCase()}):t('inventory.operations.transferQuestion',{quantity:form.quantity||'0',unit:product.value?.base_unit_symbol??''}),icon:'pi pi-exclamation-triangle',rejectProps:{label:t('common.cancel'),severity:'secondary',outlined:true},acceptProps:{label:t('inventory.operations.confirm'),severity:props.mode==='exit'?'danger':'success'},accept:()=>void save()})}
async function save():Promise<void>{saving.value=true;errors.value={};try{const body=pending.value??payload();pending.value=body;sessionStorage.setItem(storageKey.value,JSON.stringify(body));const response=await axios.post(`/inventory/${props.mode==='exit'?'exits':'transfers'}`,body,{headers:{Accept:'application/json'}});resultId.value=Number(response.data.data.movement_id??response.data.data.transfer_id);pending.value=null;sessionStorage.removeItem(storageKey.value);toast.add({severity:'success',summary:t('inventory.operations.success'),detail:response.data.message,life:6000})}catch(error:unknown){if(axios.isAxiosError(error)&&error.response?.status===422){errors.value=(error.response.data as {errors?:Record<string,string[]>}).errors??{};pending.value=null;sessionStorage.removeItem(storageKey.value)}const detail=Object.values(errors.value).flat().join(' ')||t('common.operationFailed');toast.add({severity:'error',summary:t('inventory.operations.errorTitle'),detail,life:8000})}finally{saving.value=false}}
function reset():void{resultId.value=null;errors.value={};pending.value=null;sessionStorage.removeItem(storageKey.value);form.product_id='';form.reference='';form.notes='';form.quantity='';form.responsible_name=''}
</script>

<template><Head :title="`${title} | ${t('common.appName')}`"/><Toast/><ConfirmDialog/><main class="operation-page"><InventoryNav/><header><h1>{{title}}</h1><p>{{t('inventory.operations.lead')}}</p></header>
<section class="notice"><i class="pi pi-info-circle"/><span>Solo se muestran productos con existencia disponible. Primero filtra por categoría y luego busca por código o nombre.</span></section>
<section class="panel"><div class="grid">
<label>{{t('inventory.entries.category')}}<select v-model="categoryId" :disabled="saving||pending!==null||resultId!==null"><option value="">{{t('inventory.entries.allCategories')}}</option><option v-for="category in categories" :key="category.id" :value="category.id">{{category.name}}</option></select></label>
<label class="wide">{{t('common.product')}} *<Select v-model="form.product_id" :options="availableProducts" option-label="label" option-value="id" :filter-fields="['sku','name','category_name']" filter show-clear :placeholder="t('inventory.entries.chooseProduct')" :filter-placeholder="t('inventory.entries.searchProduct')" :disabled="saving||pending!==null||resultId!==null"><template #option="{option}"><div class="product-option"><strong>{{option.sku}} — {{option.name}}</strong><small>{{option.category_name}} · Disponible: {{option.stock_quantity}} {{option.base_unit_symbol}}</small></div></template></Select></label>
<label v-if="mode==='exit'">{{t('common.location')}} *<select v-model="form.location_id" required :disabled="!form.product_id||saving||pending!==null||resultId!==null"><option value="">{{t('common.select')}}</option><option v-for="item in sourceLocations" :key="item.id" :value="item.id">{{item.name}}</option></select><small v-if="form.product_id&&!sourceLocations.length">El producto no tiene existencia en ninguna ubicación.</small></label>
<template v-else><label>{{t('inventory.operations.source')}} *<select v-model="form.source_location_id" required :disabled="!form.product_id||saving||pending!==null||resultId!==null"><option value="">{{t('common.select')}}</option><option v-for="item in sourceLocations" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label>{{t('inventory.operations.destination')}} *<select v-model="form.destination_location_id" required :disabled="!form.source_location_id||saving||pending!==null||resultId!==null"><option value="">{{t('common.select')}}</option><option v-for="item in destinationLocations" :key="item.id" :value="item.id">{{item.name}}</option></select><small>La bodega y ubicación de destino quedan identificadas en el traslado.</small></label><label>{{t('inventory.operations.responsible')}} *<input v-model.trim="form.responsible_name" list="transfer-responsibles" maxlength="180" required placeholder="Nombre del responsable"/><datalist id="transfer-responsibles"><option v-for="item in responsibles" :key="item.id" :value="item.name">{{item.code}}</option></datalist></label></template>
<label v-if="mode==='exit'">{{t('common.unit')}} *<select v-model="form.unit_id" required :disabled="saving||pending!==null||resultId!==null"><option value="">{{t('common.select')}}</option><option v-for="item in product?.units??[]" :key="item.id" :value="item.id">{{item.name}} ({{item.symbol}})</option></select></label>
<label v-if="mode==='exit'">{{t('inventory.operations.reason')}} *<select v-model="form.reason"><option value="sale">{{t('inventory.operations.sale')}}</option><option value="work_order">{{t('inventory.operations.workOrder')}}</option><option value="production">{{t('inventory.operations.production')}}</option><option value="internal_consumption">{{t('inventory.operations.consumption')}}</option><option value="waste">{{t('inventory.operations.waste')}}</option><option value="adjustment">{{t('inventory.operations.adjustment')}}</option></select></label>
<label>{{t('common.quantity')}} {{mode==='transfer'?`(${product?.base_unit_symbol??t('inventory.operations.baseUnit')})`:''}} *<input v-model.trim="form.quantity" inputmode="decimal" placeholder="0" required/></label><label>{{t('common.date')}} *<input v-model="form.document_date" type="date" :max="today" required/></label><label>{{t('common.reference')}}<input v-model.trim="form.reference" maxlength="100" :placeholder="t('inventory.operations.referencePlaceholder')"/></label><label class="wide">{{t('common.notes')}}<textarea v-model.trim="form.notes" maxlength="1000"/></label></div>
<p v-if="productLabel" class="selection">Seleccionado: <strong>{{productLabel}}</strong></p><ul v-if="Object.keys(errors).length" class="errors" role="alert"><li v-for="(messages,field) in errors" :key="field">{{messages.join(' ')}}</li></ul><div class="buttons"><Button v-if="resultId===null" :label="t(mode==='exit'?'inventory.operations.confirmExit':'inventory.operations.confirmTransfer')" icon="pi pi-check" :severity="mode==='exit'?'danger':'success'" :loading="saving" @click="submit"/><Button v-else :label="t('inventory.operations.another')" icon="pi pi-plus" @click="reset"/><Link href="/">{{t('common.cancel')}}</Link></div></section></main></template>

<style scoped>.operation-page{max-width:1050px;margin:auto;padding:clamp(1rem,3vw,2.5rem);font-family:system-ui,sans-serif}header p{color:var(--p-text-muted-color)}.notice{display:flex;gap:.65rem;align-items:center;margin-top:1rem;padding:.9rem 1rem;border-radius:.75rem;background:var(--p-blue-50);color:var(--p-blue-800)}.panel{margin-top:1rem;padding:1.5rem;border:1px solid var(--p-content-border-color);border-radius:1rem;background:var(--p-content-background)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.wide{grid-column:1/-1}label{display:grid;gap:.4rem;font-weight:650}label small,.product-option small{color:var(--p-text-muted-color);font-weight:400}.product-option{display:grid;gap:.2rem}input,select,textarea{width:100%;padding:.75rem;border:1px solid var(--p-content-border-color);border-radius:.5rem;background:var(--p-form-field-background);color:var(--p-text-color)}textarea{min-height:6rem}.selection{padding:.7rem;border-radius:.5rem;background:var(--p-content-hover-background)}.buttons{display:flex;align-items:center;gap:1rem;margin-top:1.5rem;flex-wrap:wrap}.buttons a{color:var(--p-primary-color)}.errors{color:var(--p-red-400);line-height:1.6}@media(max-width:700px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
